head.b:skin:
:root{
  --font-main:'Tajawal', 'Segoe UI', Tahoma, Arial, sans-serif;
  --clr-bg:#f7f7f9;
  --clr-surface:#ffffff;
  --clr-text:#20232a;
  --clr-muted:#6b7280;
  --clr-primary:#0f766e;
  --clr-primary-dark:#0b5c56;
  --clr-border:#e6e6ea;
  --radius:12px;
  --maxw:1180px;
}
*{box-sizing:border-box;}
html{scroll-behavior:smooth;}
body{
  margin:0; background:var(--clr-bg); color:var(--clr-text);
  font-family:var(--font-main); line-height:1.9; font-size:17px;
  direction:rtl; text-align:right; -webkit-font-smoothing:antialiased;
}
a{color:var(--clr-primary); text-decoration:none;}
a:hover{color:var(--clr-primary-dark);}
img{max-width:100%; height:auto; display:block; border-radius:8px;}
h1,h2,h3,h4{line-height:1.4; font-weight:700; margin:0 0 .5em;}
.container{max-width:var(--maxw); margin:0 auto; padding:0 16px;}

/* Header */
.site-header{background:var(--clr-surface); border-bottom:1px solid var(--clr-border); padding:16px 0; position:sticky; top:0; z-index:50;}
.site-header .container{display:flex; align-items:center; justify-content:space-between; gap:16px; flex-wrap:wrap;}
.site-title{font-size:26px; font-weight:900; color:var(--clr-text);}
.site-title a{color:inherit;}
.site-desc{color:var(--clr-muted); font-size:13px; margin-top:2px;}

/* Nav */
.main-nav ul{list-style:none; display:flex; gap:18px; margin:0; padding:0; flex-wrap:wrap;}
.main-nav a{font-weight:500; color:var(--clr-text);}
.main-nav a:hover{color:var(--clr-primary);}

/* Layout */
.layout{max-width:var(--maxw); margin:24px auto; padding:0 16px; display:grid; grid-template-columns:2.4fr 1fr; gap:24px;}
@media (max-width:860px){ .layout{grid-template-columns:1fr;} }

/* Post card */
.post{background:var(--clr-surface); border:1px solid var(--clr-border); border-radius:var(--radius); padding:20px; margin-bottom:20px;}
.post-title{font-size:22px;}
.post-title a{color:var(--clr-text);}
.post-meta{color:var(--clr-muted); font-size:13px; margin:6px 0 14px; display:flex; gap:12px; flex-wrap:wrap;}
.post-thumb{margin-bottom:14px; overflow:hidden; border-radius:10px;}
.post-thumb img{width:100%; aspect-ratio:16/9; object-fit:cover;}
.post-snippet{color:#3a3d44;}
.read-more{display:inline-block; margin-top:10px; font-weight:700;}
.post-body img, .post-body iframe{max-width:100%; border-radius:8px;}
/* Hide the duplicate hero image (already shown as featured/thumbnail above the article) */
.post-body > [dir="rtl"] > img:first-child{display:none;}
.post-labels a{display:inline-block; background:#eef2f2; color:var(--clr-primary-dark); font-size:12px; padding:4px 10px; border-radius:999px; margin:2px 4px 0 0;}

/* Tags at the bottom of the post */
.post-tags{display:flex; align-items:center; gap:8px; flex-wrap:wrap; margin-top:16px; padding-top:16px; border-top:1px solid var(--clr-border);}
.post-tags .tags-label{font-weight:700; color:var(--clr-text); font-size:14px;}
.post-tags .tag-item{display:inline-block; background:#eef2f2; color:var(--clr-primary-dark); font-size:12px; font-weight:600; padding:5px 12px; border-radius:999px; text-decoration:none; transition:background .2s, color .2s;}
.post-tags .tag-item:hover{background:var(--clr-primary); color:#fff;}

/* Share buttons */
.post-share{display:flex; align-items:center; gap:8px; flex-wrap:wrap; margin-top:22px; padding-top:16px; border-top:1px solid var(--clr-border);}
.post-share .share-label{font-weight:700; color:var(--clr-text); font-size:14px; margin-left:4px;}
.share-btn{display:inline-flex; align-items:center; gap:7px; padding:8px 14px; border-radius:999px; font-size:13px; font-weight:700; color:#fff; text-decoration:none; transition:opacity .2s, transform .2s; border:0; cursor:pointer; line-height:1;}
.share-btn:hover{opacity:.85; transform:translateY(-1px); color:#fff;}
.share-btn svg{width:16px; height:16px; fill:#fff; display:inline-block; vertical-align:middle;}
.share-fb{background:#1877f2;}
.share-x{background:#000;}
.share-wa{background:#25d366;}
.share-tg{background:#229ed9;}
.share-in{background:#0a66c2;}
.share-copy{background:#6b7280;}

/* Sidebar */
.sidebar .widget{background:var(--clr-surface); border:1px solid var(--clr-border); border-radius:var(--radius); padding:16px; margin-bottom:18px;}
.widget-title{font-size:16px; border-bottom:2px solid var(--clr-primary); padding-bottom:8px; margin-bottom:12px; display:inline-block;}
.PopularPosts ul, .BlogArchive ul, .Label ul{list-style:none; margin:0; padding:0;}
.PopularPosts li, .Label li{padding:8px 0; border-bottom:1px dashed var(--clr-border); font-size:14px;}
.PopularPosts li:last-child, .Label li:last-child{border-bottom:none;}

/* Search box */
.search-box{display:flex; gap:6px;}
.search-box input[type="text"]{flex:1; padding:10px; border:1px solid var(--clr-border); border-radius:8px; font-family:var(--font-main);}
.search-box button{padding:10px 14px; border:0; border-radius:8px; background:var(--clr-primary); color:#fff; cursor:pointer; font-weight:700;}

/* Pager */
.blog-pager{display:flex; justify-content:space-between; margin:20px 0;}
.blog-pager a{background:var(--clr-surface); border:1px solid var(--clr-border); padding:10px 18px; border-radius:8px; font-weight:700;}

/* Footer */
.site-footer{background:#101418; color:#c8ccd2; padding:32px 0; margin-top:40px; text-align:center; font-size:14px;}
.site-footer a{color:#9fe0d8;}
.footer-social{display:flex; justify-content:center; gap:10px; flex-wrap:wrap; margin-bottom:20px;}
.footer-social .social-item{display:inline-flex; align-items:center; gap:7px; background:#1b232b; border:1px solid #2a343e; color:#9fe0d8; padding:8px 14px; border-radius:999px; font-size:13px; font-weight:600; text-decoration:none; transition:background .2s, color .2s;}
.footer-social .social-item:hover{background:var(--clr-primary); color:#fff; border-color:var(--clr-primary);}
.footer-social svg{width:15px; height:15px; fill:currentColor;}
.footer-social .footer-social-title{width:100%; margin-bottom:2px; color:#7d8790; font-size:13px;}

/* Comments */
#comments{background:var(--clr-surface); border:1px solid var(--clr-border); border-radius:var(--radius); padding:20px; margin-top:20px;}

/* Ad slots */
.ad-slot{margin:20px auto; text-align:center;}
.ad-slot::before{content:'إعلان'; display:block; font-size:11px; color:var(--clr-muted); margin-bottom:6px; letter-spacing:1px;}
.ad-slot .ad-inner{background:var(--clr-surface); border:1px dashed var(--clr-border); border-radius:8px; overflow:hidden; margin:0 auto; display:flex; align-items:center; justify-content:center;}
.ad-below-header{min-height:100px;}
.ad-below-header .ad-inner{max-width:970px; min-height:90px;}
.ad-in-post{min-height:280px;}
.ad-in-post .ad-inner{min-height:250px; max-width:100%;}
.ad-before-comments .ad-inner{min-height:100px;}
.ad-footer-top .ad-inner{min-height:90px; max-width:970px;}
.ad-sidebar .ad-inner{min-height:250px;}
.ad-sidebar.sticky-ad{position:sticky; top:90px;}
@media (max-width:860px){ .ad-sidebar.sticky-ad{position:static;} }

/* Utility */
.visually-hidden{position:absolute; width:1px; height:1px; overflow:hidden; clip:rect(0 0 0 0);}
.skip-link{position:absolute; right:-999px; top:0; background:#000; color:#fff; padding:10px; z-index:999;}
.skip-link:focus{right:10px;}

body.script:
(function(){
  // ضع الإعلان الداخلي بعد الفقرة الثانية من المقال بدلاً من نهايته (مثل القوالب الاحترافية)
  var body = document.querySelector('.js-post-body');
  var adInPost = document.querySelector('.js-in-post-ad');
  if(body && adInPost){
    var paras = body.querySelectorAll('p');
    if(paras.length >= 2){
      paras[1].parentNode.insertBefore(adInPost, paras[1].nextSibling);
    }
  }
  // ضع إعلان "قبل التعليقات" مباشرة فوق صندوق التعليقات
  var comments = document.getElementById('comments');
  var adBeforeComments = document.querySelector('.js-before-comments-ad');
  if(comments && adBeforeComments){
    comments.parentNode.insertBefore(adBeforeComments, comments);
  }
})();

function sharePopup(link){
  var w = window.open(link.href, 'share', 'width=640,height=520,menubar=no,toolbar=no');
  if(w){ return false; }
  return true;
}
function copyPostLink(btn){
  var text = window.location.href;
  var done = function(){ btn.innerHTML = 'تم النسخ ✓'; setTimeout(function(){ btn.innerHTML = 'نسخ الرابط'; }, 2000); };
  if (navigator.clipboard && navigator.clipboard.writeText) {
    navigator.clipboard.writeText(text).then(done, function(){ legacyCopy(text); done(); });
  } else {
    legacyCopy(text);
    done();
  }
}
function legacyCopy(text){
  var area = document.createElement('textarea');
  area.value = text;
  area.style.position = 'fixed';
  area.style.opacity = '0';
  document.body.appendChild(area);
  area.focus();
  area.select();
  try { document.execCommand('copy'); } catch(e){}
  document.body.removeChild(area);
}
